// Exact grouped fibre-Q solver for odd-perfect (18,0), K=21 compressed HITs.
// For each pair of fibre supports, retain the smallest compressed
// SG=sum_j G_j^2.  The fibre side has H_j=NPAF_alpha(j)+NPAF_gamma(j), and
// exact projection gives 2Q=SG+SH with SH=sum_j H_j^2.  Q<=57 is necessary.
// The negacyclic cross equation alpha gamma* - gamma alpha*=0 is solved by
// exact GF(3) nullspace sign enumeration, followed by the original integer
// equations.  Global signs of alpha and gamma are quotiented only at this Q
// stage: cross=0 and NPAF/SH are separately invariant under either sign flip.
#include <bits/stdc++.h>
#include <omp.h>
using namespace std;static const int N=25;using A=array<int,N>;using Vec=array<int16_t,N>;
Vec comm_mask(uint32_t asupp,uint32_t amask,int j){Vec f{};auto add=[&](int e,int v){if(e>=0)f[e]+=v;else f[e+N]-=v;};for(int i=0;i<N;i++)if(asupp>>i&1){int ai=(amask>>i&1)?1:-1;add(i-j,ai);add(j-i,-ai);}return f;}
Vec comm(const A&a,const A&g){Vec f{};auto add=[&](int e,int v){if(e>=0)f[e]+=v;else f[e+N]-=v;};for(int i=0;i<N;i++)if(a[i])for(int j=0;j<N;j++)if(g[j]){add(i-j,a[i]*g[j]);add(j-i,-g[j]*a[i]);}return f;}
vector<uint32_t> solve_gamma(uint32_t asupp,uint32_t amask,uint32_t gsupp){vector<int>sp;for(int i=0;i<N;i++)if(gsupp>>i&1)sp.push_back(i);int nc=sp.size();if(!nc)return{0};vector<vector<uint8_t>>a(12,vector<uint8_t>(nc));for(int j=0;j<nc;j++){auto v=comm_mask(asupp,amask,sp[j]);for(int r=1;r<=12;r++){int z=v[r]%3;if(z<0)z+=3;a[r-1][j]=z;}}int rr=0;vector<int>piv;for(int c=0;c<nc&&rr<12;c++){int q=-1;for(int r=rr;r<12;r++)if(a[r][c]){q=r;break;}if(q<0)continue;swap(a[rr],a[q]);if(a[rr][c]==2)for(int j=0;j<nc;j++)a[rr][j]=(2*a[rr][j])%3;for(int r=0;r<12;r++)if(r!=rr&&a[r][c]){int f=a[r][c];for(int j=0;j<nc;j++)a[r][j]=(a[r][j]+6-f*a[rr][j])%3;}piv.push_back(c);rr++;}vector<char>isp(nc);for(int c:piv)isp[c]=1;vector<int>fr;for(int c=0;c<nc;c++)if(!isp[c])fr.push_back(c);int d=fr.size();if(d>24)abort();vector<uint32_t>sol;uint64_t M=1ULL<<d;array<int,25>x{};A aa{};for(int i=0;i<N;i++)if(asupp>>i&1)aa[i]=(amask>>i&1)?1:-1;for(uint64_t m=0;m<M;m++){fill(x.begin(),x.end(),0);for(int k=0;k<d;k++)x[fr[k]]=(m>>k&1)?2:1;bool ok=true;for(int r=rr-1;r>=0;r--){int ss=0;for(int k=0;k<d;k++)ss=(ss+a[r][fr[k]]*x[fr[k]])%3;int z=(3-ss)%3;if(z!=1&&z!=2){ok=false;break;}x[piv[r]]=z;}if(!ok||x[0]!=1)continue;A ga{};uint32_t mask=0;for(int j=0;j<nc;j++){int sg=x[j]==1?1:-1;ga[sp[j]]=sg;if(sg==1)mask|=1u<<sp[j];}auto z=comm(aa,ga);bool ex=true;for(int r=0;r<N;r++)if(z[r]){ex=false;break;}if(ex)sol.push_back(mask);}return sol;}
inline int npaf(uint32_t supp,uint32_t plus,int r){uint32_t pair=supp&(supp>>r),sx=plus^(plus>>r);int non=__builtin_popcount(pair)-2*__builtin_popcount(pair&sx);uint32_t mr=(1u<<r)-1,hi=supp>>(N-r),lo=supp&mr,pw=hi&lo,sh=plus>>(N-r),sl=plus&mr;int wrap=__builtin_popcount(pw)-2*__builtin_popcount(pw&(sh^sl));return non-wrap;}
int sg_of(const A&p,const A&c){int s=0;for(int r=1;r<=12;r++){int g=0;for(int i=0;i<N;i++)g+=p[i]*p[(i+r)%N]+c[i]*c[(i+r)%N];s+=g*g;}return s;}
struct Key{uint32_t as,gs;bool operator<(Key const&o)const{return as!=o.as?as<o.as:gs<o.gs;}};struct Group{Key k{};int minSG=1000000000,count=0;};
int main(int argc,char**argv){if(argc<2)return 2;ifstream f(argv[1]);string line;map<Key,Group>mp;long long hits=0;while(getline(f,line)){if(line.rfind("HIT ",0))continue;auto a=line.find("p=")+2,b=line.find("|c=");string ps=line.substr(a,b-a),cs=line.substr(b+3);replace(ps.begin(),ps.end(),',',' ');replace(cs.begin(),cs.end(),',',' ');stringstream sp(ps),sc(cs);A p{},c{};uint32_t as=0,gs=0;for(int i=0;i<N;i++){sp>>p[i];if(!p[i])as|=1u<<i;}for(int i=0;i<N;i++){sc>>c[i];if(!c[i])gs|=1u<<i;}Key k{as,gs};auto&g=mp[k];g.k=k;g.count++;g.minSG=min(g.minSG,sg_of(p,c));hits++;}vector<Group>groups;for(auto&kv:mp)groups.push_back(kv.second);cout<<"QGROUP_INPUT hits="<<hits<<" groups="<<groups.size()<<"\n";atomic<long long>alphas{0},half{0},qpass{0};atomic<int>minMargin{INT_MAX},minSHglobal{INT_MAX};
#pragma omp parallel for schedule(dynamic,1)
for(int gi=0;gi<(int)groups.size();gi++){auto G=groups[gi];vector<int>apos;for(int i=0;i<N;i++)if(G.k.as>>i&1)apos.push_back(i);int ZA=apos.size();long long lh=0,lq=0;int lmin=INT_MAX;uint32_t AM=1u<<(ZA-1);for(uint32_t m=0;m<AM;m++){uint32_t ap=1u<<apos[0];for(int t=1;t<ZA;t++)if(m>>(t-1)&1)ap|=1u<<apos[t];alphas++;int ha[13];for(int r=1;r<=12;r++)ha[r]=npaf(G.k.as,ap,r);auto sols=solve_gamma(G.k.as,ap,G.k.gs);lh+=sols.size();for(uint32_t gp:sols){int sh=0;for(int r=1;r<=12;r++){int h=ha[r]+npaf(G.k.gs,gp,r);sh+=h*h;}lmin=min(lmin,sh);if(G.minSG+sh<=114){lq++;
#pragma omp critical
cout<<"QHIT as="<<G.k.as<<" gs="<<G.k.gs<<" minSG="<<G.minSG<<" sh="<<sh<<" Q="<<(G.minSG+sh)/2<<" amask="<<ap<<" gmask="<<gp<<"\n";}}}half+=lh;qpass+=lq;int old=minSHglobal.load();while(lmin<old&&!minSHglobal.compare_exchange_weak(old,lmin)){}int mar=G.minSG+lmin-114;old=minMargin.load();while(mar<old&&!minMargin.compare_exchange_weak(old,mar)){} }
cout<<"K21_QGROUP_SUMMARY groups="<<groups.size()<<" alphas="<<alphas<<" half_gamma_solutions="<<half<<" Q_feasible_halfgamma="<<qpass<<" minSH="<<minSHglobal<<" min_margin="<<minMargin<<"\n";}
